#dyn-message-theme[data-theme="tmpl-liquid-glass"]  {
  --p-hot:  color-mix(in srgb, var(--primary) 42%, white);
  --p-soft: color-mix(in srgb, var(--primary) 48%, transparent);
  --p-haze: color-mix(in srgb, var(--primary) 18%, transparent);
  --s-hot:  color-mix(in srgb, var(--secondary) 38%, white);
  --s-soft: color-mix(in srgb, var(--secondary) 45%, transparent);
  --s-haze: color-mix(in srgb, var(--secondary) 16%, transparent);
  background: var(--background, #061014);
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .dyn-stage  {
  background:
    radial-gradient(80cqw 60cqh at 18% 80%, var(--p-haze), transparent 58%),
    radial-gradient(70cqw 50cqh at 88% 8%, var(--s-haze), transparent 55%),
    linear-gradient(180deg,
      color-mix(in srgb, var(--background) 78%, white) 0%,
      var(--background) 52%,
      color-mix(in srgb, var(--background) 86%, black) 100%);
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .wash  {
  position: absolute;
   inset: -10%;
   z-index: 1;
   pointer-events: none;
  background:
    radial-gradient(closest-side, color-mix(in srgb, var(--primary) 22%, transparent), transparent 70%) 20% 70% / 40% 30%,
    radial-gradient(closest-side, color-mix(in srgb, var(--secondary) 16%, transparent), transparent 68%) 70% 20% / 36% 28%;
  background-repeat: no-repeat;
  filter: blur(28px);
  opacity: 0.55;
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] canvas.gl  {
  position: absolute;
   inset: 0;
   z-index: 12;
  width: 100%;
   height: 100%;
  pointer-events: none;
  opacity: 0;
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .layout  {
  position: absolute;
   inset: 0;
   z-index: 8;
  display: flex;
   align-items: center;
  justify-content: flex-start;
  padding: 6cqh 6cqw;
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"].no-copy .layout  {
   justify-content: center;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .slab  {
  position: relative;
  height: 78cqh;
  aspect-ratio: 3 / 4;
  flex: none;
  opacity: 0;
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .floater  {
   position: absolute;
   inset: 0;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .slab-glass  {
  position: absolute;
   inset: 0;
  border-radius: 1.8cqw;
  background: linear-gradient(160deg, rgba(255,255,255,.14), rgba(255,255,255,.03) 46%, rgba(255,255,255,.07));
  border: 1px solid rgba(255,255,255,.26);
  box-shadow:
    0 2.2cqh 5cqh rgba(0,0,0,.4),
    inset 0 1px 0 rgba(255,255,255,.4),
    0 0 3.4cqw var(--p-haze);
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .photo-well  {
  position: absolute;
   inset: 4.6%;
  border-radius: 1.2cqw;
  overflow: hidden;
  background: var(--background);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.14);
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .photo-well img  {
  display: block;
   width: 100%;
   height: 100%;
  object-fit: cover;
  filter: saturate(1.08) contrast(1.04);
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .copy  {
  position: absolute;
   z-index: 14;
  right: 5cqw;
   top: 50%;
  width: min(46cqw, 820px);
  height: 74cqh;
  transform: translateY(-50%);
  display: flex;
   flex-direction: column;
  opacity: 0;
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .copy.gone  {
   display: none;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .msg-fit  {
  flex: 1 1 auto;
  height: 0;
  min-height: 0;
  overflow: hidden;
  display: flex;
   align-items: center;
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .msg-fit span  {
  display: block;
  width: 100%;
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-weight: 500;
  font-style: italic;
  line-height: 1.02;
  color: #f6fbff;
  overflow-wrap: normal;
  text-shadow: 0 0 22px var(--p-soft);
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .name-slot  {
  flex: none;
  height: 16cqh;
  margin-top: 3cqh;
  padding-top: 2.3cqh;
  border-top: 1px solid color-mix(in srgb, var(--primary) 32%, rgba(255,255,255,.16));
  overflow: hidden;
  display: flex;
   align-items: center;
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .name-slot.hidden  {
   display: none;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .name-fit  {
  width: 100%;
   height: 12.5cqh;
  overflow: hidden;
  display: flex;
   align-items: center;
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .name-fit span  {
  display: block;
  width: 100%;
  font-family: 'Outfit', sans-serif;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  line-height: 0.95;
  color: color-mix(in srgb, white 82%, var(--secondary));
  white-space: nowrap;
  text-shadow: 0 0 20px var(--s-soft);
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .copy.no-msg .msg-fit  {
   display: none;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .copy.no-msg .name-slot  {
  flex: 1;
   height: auto;
   margin-top: 0;
   padding-top: 0;
   border: 0;
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .copy.no-msg .name-fit  {
   height: 28cqh;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .copy.no-name .name-slot  {
   display: none;
   }
@keyframes dynLiqRise  {
  from  {
   opacity: 0;
   transform: translateY(6cqh);
   filter: blur(8px);
   }
  to    {
   opacity: 1;
   transform: none;
   filter: none;
   }
}
@keyframes dynLiqCopyIn  {
  from  {
   opacity: 0;
   transform: translateY(-50%) translateX(2.4cqw);
   filter: blur(7px);
   }
  to    {
   opacity: 1;
   transform: translateY(-50%);
   filter: none;
   }
}
@keyframes dynLiqGlIn  {
   from  {
   opacity: 0;
   } to  {
   opacity: 1;
   } }
#dyn-message-theme[data-theme="tmpl-liquid-glass"].on .slab  {
   animation: dynLiqRise var(--reveal-ms) cubic-bezier(.18,1.02,.28,1) both;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"].on .copy  {
  animation: dynLiqCopyIn calc(var(--reveal-ms) * 0.68) calc(var(--reveal-ms) * 0.24) cubic-bezier(.2,.9,.22,1) both;
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"].on canvas.gl  {
   animation: dynLiqGlIn calc(var(--reveal-ms) * 0.8) calc(var(--reveal-ms) * 0.1) ease both;
   }
@keyframes dynLiqFloat  {
  0%, 100%  {
   transform: translateY(0);
   }
  50%  {
   transform: translateY(-0.8cqh);
   }
}
#dyn-message-theme[data-theme="tmpl-liquid-glass"].on.idle .slab  {
   animation: none;
   opacity: 1;
   transform: none;
   filter: none;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"].on.idle .copy  {
   animation: none;
   opacity: 1;
   transform: translateY(-50%);
   filter: none;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"].on.idle canvas.gl  {
   animation: none;
   opacity: 1;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"].on.idle .floater  {
   animation: dynLiqFloat 10s ease-in-out infinite;
   }
@keyframes dynLiqSink  {
  to  {
   opacity: 0;
   transform: translateY(5cqh);
   filter: blur(6px);
   }
}
@keyframes dynLiqCopyOut  {
  to  {
   opacity: 0;
   transform: translateY(-50%) translateX(-1.4cqw);
   filter: blur(6px);
   }
}
@keyframes dynLiqGlOut  {
   to  {
   opacity: 0;
   } }
#dyn-message-theme[data-theme="tmpl-liquid-glass"].on.off .slab  {
   animation: dynLiqSink calc(var(--reveal-ms) * 0.48) cubic-bezier(.55,.05,.8,.3) both;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"].on.off .copy  {
   animation: dynLiqCopyOut calc(var(--reveal-ms) * 0.42) both;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"].on.off canvas.gl  {
   animation: dynLiqGlOut calc(var(--reveal-ms) * 0.4) both;
   }

/* ================================================================
   PARALLAX DRIFT
   ================================================================ */
#dyn-message-theme.dyn-portrait[data-theme="tmpl-liquid-glass"] .layout  {
  justify-content: center;
   align-items: flex-start;
   padding-top: 5cqh;
}
#dyn-message-theme.dyn-portrait[data-theme="tmpl-liquid-glass"] .slab  {
   height: 46cqh;
   }
#dyn-message-theme.dyn-portrait[data-theme="tmpl-liquid-glass"] .copy  {
  left: 7cqw;
   right: 7cqw;
   width: auto;
   top: 74%;
   height: 40cqh;
}
@keyframes dynLiqRise  {
  from  {
   opacity: 0;
   transform: translateY(6cqh);
   filter: blur(8px);
   }
  to    {
   opacity: 1;
   transform: none;
   filter: none;
   }
}
@keyframes dynLiqCopyIn  {
  from  {
   opacity: 0;
   transform: translateY(-50%) translateX(2.4cqw);
   filter: blur(7px);
   }
  to    {
   opacity: 1;
   transform: translateY(-50%);
   filter: none;
   }
}
@keyframes dynLiqGlIn  {
   from  {
   opacity: 0;
   } to  {
   opacity: 1;
   } }
@keyframes dynLiqFloat  {
  0%, 100%  {
   transform: translateY(0);
   }
  50%  {
   transform: translateY(-0.8cqh);
   }
}
@keyframes dynLiqSink  {
  to  {
   opacity: 0;
   transform: translateY(5cqh);
   filter: blur(6px);
   }
}
@keyframes dynLiqCopyOut  {
  to  {
   opacity: 0;
   transform: translateY(-50%) translateX(-1.4cqw);
   filter: blur(6px);
   }
}
@keyframes dynLiqGlOut  {
   to  {
   opacity: 0;
   } }
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .bubbles  {
   position:absolute;
   inset:0;
   z-index:11;
   pointer-events:none;
   overflow:hidden;
   }
#dyn-message-theme[data-theme="tmpl-liquid-glass"] .bubbles i  {
  position:absolute;
   left:var(--bx);
   bottom:-8%;
  width:var(--bs);
   height:var(--bs);
   border-radius:50%;
  background: radial-gradient(circle at 35% 30%, rgba(255,255,255,.55), color-mix(in srgb, var(--primary) 55%, transparent) 42%, transparent 70%);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.22), 0 0 18px color-mix(in srgb, var(--secondary) 35%, transparent);
  animation: tmpl-liq-rise var(--bdur, 14s) linear var(--bdel, 0s) infinite;
  opacity:.7;
}
@keyframes tmpl-liq-rise  {
  0%  {
   transform: translate3d(0, 0, 0) scale(.6);
   opacity:0;
   }
  12%  {
   opacity:.75;
   }
  100%  {
   transform: translate3d(var(--bdx, 4cqw), -118cqh, 0) scale(1.15);
   opacity:0;
   }
}
